public class Main {
    public static void main(String[] args) { int[] s = new int[3]; }
}

exercises.solution:
public class Main {
static String fmt(int[] a) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < a.length; i++) {
            if (i > 0) sb.append(' ');
            sb.append(a[i]);
        }
        return sb.append(']').toString();
    }
    public static void main(String[] args) {
        int[] s = {1, 2, 3};
        System.out.println(fmt(s));
    }
}

